declarations.code:
template <std::input_or_output_iterator I, std::sentinel_for<I> S>

subrange(I, S, /*make-unsigned-like-t*/<std::iter_difference_t<I>>) ->

    subrange<I, S, ranges::subrange_kind::sized>;

sections.text:
While constructing the subrange object,

for (1,2), the behavior is undefined if the iterator-sentinel pair does not denote a valid range,
 for (2,4), the behavior is undefined if the given size is not equal to the size of the range.

examples.code:
#include <ranges>
#include <vector>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    int values[]{1, 2, 3};
    std::ranges::subrange range{values, values + 3};
    assert(!range.empty() && *range.begin() == 1 && range.end() == values + 3);
    static_assert(std::ranges::input_range<decltype(range)>);
    static_assert(std::ranges::output_range<decltype(range), int>);
    static_assert(std::ranges::view<decltype(range)>);
    static_assert(std::is_same_v<std::ranges::iterator_t<decltype(range)>, int *>);
    static_assert(
        std::is_same_v<std::ranges::range_reference_t<decltype(range)>, int &>);
    static_assert(
        std::is_same_v<std::ranges::range_size_t<decltype(range)>, std::size_t>);
    static_assert(
        std::is_same_v<std::ranges::borrowed_iterator_t<decltype(range)>, int *>);
    std::ranges::subrange<int *, int *, std::ranges::subrange_kind::sized> sized{
        values, values + 3};
    assert(sized.size() == 3);
}
